export declare const campaignLaunch = "\n<!DOCTYPE html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Alerte Campagne Importante</title>\n\n<style>\n    body{\n        margin:0;\n        padding:0;\n        background-color:#f3f4f6;\n        font-family:Arial, Helvetica, sans-serif;\n        color:#111827;\n    }\n\n    .wrapper{\n        width:100%;\n        padding:40px 20px;\n        box-sizing:border-box;\n    }\n\n    .container{\n        max-width:620px;\n        margin:0 auto;\n        background:#ffffff;\n        border:1px solid #e5e7eb;\n        border-radius:10px;\n        overflow:hidden;\n    }\n\n    .header{\n        padding:28px 32px;\n        border-bottom:1px solid #e5e7eb;\n        background:#ffffff;\n    }\n\n    .header h1{\n        margin:0;\n        font-size:22px;\n        font-weight:600;\n        color:#111827;\n    }\n\n    .header p{\n        margin:8px 0 0;\n        font-size:14px;\n        color:#6b7280;\n    }\n\n    .content{\n        padding:32px;\n    }\n\n    .content p{\n        margin:0 0 18px;\n        line-height:1.7;\n        font-size:15px;\n        color:#374151;\n    }\n\n    .alert-box{\n        margin:28px 0;\n        border:1px solid #e5e7eb;\n        background:#f9fafb;\n        border-radius:8px;\n        overflow:hidden;\n    }\n\n    .info-row{\n        display:flex;\n        padding:14px 18px;\n        border-bottom:1px solid #e5e7eb;\n        font-size:14px;\n    }\n\n    .info-row:last-child{\n        border-bottom:none;\n    }\n\n    .label{\n        width:190px;\n        font-weight:600;\n        color:#111827;\n    }\n\n    .value{\n        flex:1;\n        color:#374151;\n    }\n\n    .status-badge{\n        display:inline-block;\n        padding:3px 8px;\n        font-size:12px;\n        border-radius:6px;\n        background:#e5e7eb;\n        color:#111827;\n    }\n\n    .notice{\n        margin-top:30px;\n        padding-top:20px;\n        border-top:1px solid #e5e7eb;\n        font-size:14px;\n        line-height:1.7;\n        color:#6b7280;\n    }\n\n    .footer{\n        padding:20px 32px;\n        background:#f9fafb;\n        border-top:1px solid #e5e7eb;\n        font-size:12px;\n        color:#9ca3af;\n        text-align:center;\n    }\n\n    @media only screen and (max-width:600px){\n        .content,\n        .header,\n        .footer{\n            padding:24px;\n        }\n\n        .info-row{\n            display:block;\n        }\n\n        .label{\n            width:100%;\n            margin-bottom:6px;\n        }\n    }\n</style>\n</head>\n\n<body>\n\n<div class=\"wrapper\">\n\n    <div class=\"container\">\n\n        <!-- Header -->\n        <div class=\"header\">\n            <h1>Campagne en file d\u2019attente</h1>\n            <p>Notification syst\u00E8me \u2014 volume \u00E9lev\u00E9 d\u00E9tect\u00E9</p>\n        </div>\n\n        <!-- Content -->\n        <div class=\"content\">\n\n            <p>Bonjour Administrateur,</p>\n\n            <p>\n                Une campagne SMS de volume important vient d\u2019\u00EAtre plac\u00E9e en file d\u2019attente.\n                Une surveillance est recommand\u00E9e afin d\u2019assurer un traitement conforme et s\u00E9curis\u00E9.\n            </p>\n\n            <!-- Alert Box -->\n            <div class=\"alert-box\">\n\n                <div class=\"info-row\">\n                    <div class=\"label\">Soci\u00E9t\u00E9</div>\n                    <div class=\"value\">%tenant_name%</div>\n                </div>\n\n                <div class=\"info-row\">\n                    <div class=\"label\">Campagne</div>\n                    <div class=\"value\">%campaign_name%</div>\n                </div>\n\n                <div class=\"info-row\">\n                    <div class=\"label\">Volume estim\u00E9</div>\n                    <div class=\"value\">%volume_estimate%</div>\n                </div>\n\n                <div class=\"info-row\">\n                    <div class=\"label\">Exp\u00E9diteur</div>\n                    <div class=\"value\">%sender_name%</div>\n                </div>\n\n                <div class=\"info-row\">\n                    <div class=\"label\">Statut anti-fraude</div>\n                    <div class=\"value\">\n                        <span class=\"status-badge\">%anti_fraud_status%</span>\n                    </div>\n                </div>\n\n            </div>\n\n            <div class=\"notice\">\n                Cette alerte est g\u00E9n\u00E9r\u00E9e automatiquement lorsqu\u2019une campagne d\u00E9passe un certain seuil de volume.\n                Aucune action imm\u00E9diate n\u2019est requise sauf indication contraire du syst\u00E8me de s\u00E9curit\u00E9.\n            </div>\n\n        </div>\n\n        <!-- Footer -->\n        <div class=\"footer\">\n            \u00A9 %current_year% Plateforme SaaS SMS Marketing \u2014 Surveillance des campagnes\n        </div>\n\n    </div>\n\n</div>\n\n</body>\n</html>\n";
